mapper.update:
update p_quota_balance set reserved_units=reserved_units-#{units},used_units=used_units+#{usedUnits},
  revision=revision+1,updated_at=utc_timestamp(3)
where account_id=#{accountId} and quota_type='TTS_CHAR' and reserved_units >= #{units}
  and granted_units-used_units >= #{usedUnits}
